@Test
public void testHasOption_ShortOptionNamePassedAsLong() {
    // The hasOption(String opt) method specifically checks for the full name.
    // If a short option name is passed as a string, it should return false
    // unless the short name *is* also the full name (which is unusual but possible).
    Option shortOption = new Option("v", false, "Verbose");
    commandLine.addOption(shortOption);

    assertFalse(commandLine.hasOption("v")); // Expecting false as "v" is not the long name
    // If "v" had a long name "verbose", this would be true, but it doesn't in this setup.
    // The specification states 'identified by its full name', and 'v' is not the full name here.
